class Diagram(Flowable):
 """Compact vector architecture/graph figures: readable and searchable text."""
 def __init__(self,rows):super().__init__();self.rows=rows;self.width=487;self.height=len(rows)*71+8
 def draw(self):
  c=self.canv;cols=max(len(row) for row in self.rows);gap=13;w=(self.width-gap*(cols-1))/cols
  for i,row in enumerate(self.rows):
   y=self.height-(i+1)*71
   for k,label in enumerate(row):
    x=k*(w+gap);c.setFillColor(colors.HexColor('#F2EFFF'));c.setStrokeColor(PURPLE);c.roundRect(x,y,w,55,6,fill=1,stroke=1)
    lines=label.split('\n');c.setFillColor(INK);c.setFont('BodyBold',8)
    for z,line in enumerate(lines):c.drawCentredString(x+w/2,y+40-z*12,line)
    if k<len(row)-1:
     c.line(x+w,y+28,x+w+gap,y+28);c.line(x+w+gap,y+28,x+w+gap-4,y+31);c.line(x+w+gap,y+28,x+w+gap-4,y+25)
   if i<len(self.rows)-1:
    c.line(w/2,y,w/2,y-16);c.line(w/2,y-16,w/2-3,y-12);c.line(w/2,y-16,w/2+3,y-12)

class Doc(BaseDocTemplate):
 def __init__(self,path,title):
  super().__init__(str(path),pagesize=A4,leftMargin=54,rightMargin=54,topMargin=55,bottomMargin=49,title=title,author='ПРУФ-ИТ',subject='Инженерная документация и воспроизводимая валидация',pageCompression=1)
  self.counter=0;self.addPageTemplates(PageTemplate(id='standard',frames=Frame(54,49,A4[0]-108,A4[1]-104,id='body'),onPage=self.page))
 def page(self,c,d):
  c.saveState();c.setStrokeColor(PURPLE);c.setLineWidth(1);c.line(54,A4[1]-34,A4[0]-54,A4[1]-34)
  c.setFont('BodyBold',8);c.setFillColor(PURPLE);c.drawString(54,A4[1]-25,'ПРУФ-ИТ / PROOFIT · ENGINEERING EVIDENCE')
  c.setFont('Body',7);c.setFillColor(GRAY);c.drawString(54,27,DATE+' · документ связан с текущей реализацией');c.drawRightString(A4[0]-54,27,str(d.page));c.restoreState()
 def afterFlowable(self,f):
  if isinstance(f,Paragraph) and f.style.name in ('H1','H2'):
   level=0 if f.style.name=='H1' else 1;self.counter+=1;key='section-'+str(self.counter)
   self.canv.bookmarkPage(key);self.canv.addOutlineEntry(f.getPlainText(),key,level=level,closed=False)
   self.notify('TOCEntry',(level,f.getPlainText(),self.page,key))
 def beforeDocument(self):
  self.counter=0

