def table(rows):
 width=487;cols=len(rows[0]);ratios=[1/cols]*cols
 if cols==3:ratios=[.22,.43,.35]
 if cols==4:ratios=[.15,.26,.32,.27]
 body=[[Paragraph(str(cell),ST['Small']) for cell in row]for row in rows]
 t=Table(body,colWidths=[width*v for v in ratios],repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#E8E1FF')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F8F9FC')]),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#D8DCEA')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));return t
